REPLACE INTO `barangay_hazards` (`id`, `barangay_profile_id`, `hazard_type`, `risk_level`, `risk_score`, `description`, `exposure_scope`, `focus_area`, `source_agency`, `source_reference_number`, `reference_title`, `reference_year`, `reference_url`, `date_assessed`, `external_source_id`, `metadata`, `created_at`, `updated_at`) VALUES
	(45, 9, 'Flood', 'High', 75, 'San Agustin is listed under QC Drainage Master Plan coverage with ALL STREETS noted among Phase I/II assessed localities. Low-lying residential streets experience street flooding and prolonged ponding during intense rainfall and typhoon-enhanced monsoon events; drainage capacity and creek/tributary overflow are primary drivers.', 'zone_specific', 'Barangay San Agustin — all streets under QC Drainage Master Plan Phase I/II assessed coverage; prioritize low-lying / drainage-constrained residential streets and ponding hotspots during heavy rainfall.', 'MDRRMO', 'QCDMP-V1-APP-A / Brgy. San Agustin', 'Quezon City Drainage Master Plan (Phase I & II) — Areas Covered / Site Assessment', 2025, 'https://quezoncity.gov.ph/qc-profile/drainage-master-plan/', '2026-07-05', NULL, '{"seeded":true,"capstone_focus":true,"training_recommendations":["Flood Preparedness and Early Warning","Flood Preparedness and Evacuation"]}', '2026-07-26 07:50:03', '2026-07-26 07:50:03'),
	(46, 9, 'Typhoon', 'High', 75, 'Strong winds and extreme rainfall from tropical cyclones compound local flooding in Novaliches. Dense housing and roadside utilities raise exposure to wind damage, downed lines, and interrupted access during storms that also trigger flood conditions identified in the QC Drainage Master Plan.', 'barangay_wide', 'Whole of Barangay San Agustin (Novaliches, QC) — wind, rainfall, and utility disruption can affect residential areas barangay-wide during tropical cyclones.', 'PAGASA', 'PAGASA-NCR-TC / QCDMP rainfall context', 'Tropical cyclone / monsoon rainfall impacts in NCR urban catchments (context for QC flood studies)', 2024, 'https://www.pagasa.dost.gov.ph/', '2026-06-28', NULL, '{"seeded":true,"capstone_focus":true,"training_recommendations":["Typhoon Preparedness","Flood Preparedness and Early Warning"]}', '2026-07-26 07:50:03', '2026-07-26 07:50:03'),
	(47, 9, 'Earthquake', 'Moderate', 50, 'Metro Manila including Quezon City is exposed to strong ground shaking from West Valley Fault and other regional sources. Barangay-level preparedness should assume damaging shaking scenarios; use HazardHunterPH / PHIVOLCS GeoHazards Portal for parcel-level ground shaking and related layers when planning drills.', 'barangay_wide', 'Whole of Barangay San Agustin — ground shaking is treated as barangay-wide (no single street pin); drills cover households and assembly areas across the barangay.', 'PHIVOLCS', 'PHIVOLCS / HazardHunterPH — NCR ground shaking', 'PHIVOLCS Earthquake Hazard Maps / HazardHunterPH location assessment (NCR)', 2024, 'https://hazardhunter.georisk.gov.ph/map', '2026-06-16', NULL, '{"seeded":true,"capstone_focus":true,"training_recommendations":["Earthquake Drill and Evacuation","Earthquake Preparedness","Search and Rescue Awareness"]}', '2026-07-26 07:50:03', '2026-07-26 07:50:03'),
	(48, 9, 'Fire', 'Moderate', 50, 'Compact residential pockets in San Agustin create moderate structural fire-spread risk where access lanes are narrow and electrical loading is high. Community fire drills and egress planning remain priority BDRRM activities alongside flood readiness.', 'pattern_based', 'Dense residential clusters / closely packed houses and narrow access lanes in San Agustin — fire can ignite anywhere, but spread risk is higher where homes are adjacent and egress is constrained (pattern-based, not one fixed street).', 'BFP', 'BFP-QC urban densification context', 'Urban fire risk in dense residential blocks (BFP / LGU preparedness context)', 2024, 'https://bfp.gov.ph/', '2026-06-21', NULL, '{"seeded":true,"capstone_focus":true,"training_recommendations":["Basic Fire Safety and Evacuation","Fire Safety and Emergency Response"]}', '2026-07-26 07:50:03', '2026-07-26 07:50:03');
REPLACE INTO `barangay_profiles` (`id`, `philippine_barangay_id`, `barangay_name`, `municipality_city`, `province`, `region`, `barangay_address`, `contact_number`, `email_address`, `estimated_population`, `total_land_area`, `number_of_households`, `area_classification`, `hazards`, `hazard_notes`, `external_source_id`, `last_assessed_at`, `created_at`, `updated_at`) VALUES
	(9, 102, 'San Agustin', 'Quezon City', 'Metro Manila', 'NCR', 'San Agustin, Quezon City, Metro Manila', '+63 2 8988 4242', 'sanagustin.brgy@quezoncity.gov.ph', 22000, 1.15, 4800, 'Urban', '["Flood","Typhoon","Earthquake","Fire"]', 'Capstone study area: Barangay San Agustin, District 5 (Novaliches), Quezon City. Included in Quezon City Drainage Master Plan Phase I/II flood assessment coverage (all streets listed among field-validated flood-prone localities). Local BDRRM implementation studies also cite gaps in drills and early warning practice.', 'HAZ-QC-SAN-AGUSTIN-NOVALICHES-2025', '2026-07-05 07:50:03', '2026-07-26 06:59:21', '2026-07-26 07:50:03');
