	(1, 5, NULL, 'Public Safety Campaign Management System', 'Fire Safety and Emergency Response - Session 1 ??? 2026-07-10 ??? 13:28 - 14:28', '2026-07-09 04:28:58', '2026-07-09 05:52:41', 'approved', 30, 20, 0, '{"id":5,"training_module_id":5,"training_title":"Fire Safety and Emergency Response","short_description":"This training module equips participants with the fundamental knowledge and practical skills needed to prevent, respond to, and safely evacuate during fire-related emergencies. Participants will learn fire prevention strategies, the proper use of fire extinguishers, emergency response procedures, and evacuation protocols applicable in homes, schools, workplaces, and government facilities.","related_hazards":"Fire","recommended_communities":{"summary":{"total_communities":3,"high_priority":1,"medium_priority":2,"low_priority":0},"communities":[{"barangay_profile_id":7,"barangay_name":"Holy Spirit","municipality_city":"Quezon City","province":"Metro Manila","related_hazard":"Fire","risk_level":"High","priority_level":"Priority 1","priority_score":72,"recommendation_reason":"Recommended due to high fire susceptibility.","recommendation":"Recommended due to high fire susceptibility."},{"barangay_profile_id":4,"barangay_name":"Commonwealth","municipality_city":"Quezon City","province":"Metro Manila","related_hazard":"Fire","risk_level":"Medium","priority_level":"Priority 2","priority_score":55,"recommendation_reason":"Recommended based on moderate fire exposure.","recommendation":"Recommended based on moderate fire exposure."},{"barangay_profile_id":6,"barangay_name":"Bagong Silangan","municipality_city":"Quezon City","province":"Metro Manila","related_hazard":"Fire","risk_level":"Medium","priority_level":"Priority 2","priority_score":48,"recommendation_reason":"Recommended based on moderate fire exposure.","recommendation":"Recommended based on moderate fire exposure."}]},"recommended_audience":null,"estimated_duration_minutes":60,"total_lessons":3,"assigned_