	(16, 7, 20, 'Public Safety Campaign Management System', 'SEEDER: Demo Ready ? Multi-Hazard Community Resilience Week', '2026-06-23 05:40:33', '2026-07-11 05:40:33', 'scheduled', 32, 22, 0, '{"submitted_at":"2026-06-23T13:40:33+08:00","training_title":"Flood Preparedness and Early Warning","_test_seeder":"simulation_event_planning_demo","training_module_id":7,"short_description":"Training module focused on rainfall monitoring, flood mapping, and early warning communication.","recommended_communities":{"summary":{"total_communities":1,"high_priority":1,"medium_priority":0,"low_priority":0},"communities":[{"barangay_name":"Pasong Tamo","priority":"high","hazard_score":82}]},"target_audience":["Barangay Officials","Community Volunteers","Emergency Responders"],"registration_opens":"2026-06-22T13:40:33+08:00","registration_deadline":"2026-07-10T13:40:33+08:00","training_completion_deadline":"2026-07-12T13:40:33+08:00","expected_participants":32,"maximum_participants":42,"published_status":"published","registration_enabled":true,"registration_link":"http:\\/\\/127.0.0.1:8000\\/participant\\/register?campaign_request=16","registration_form_path":"\\/participant\\/register"}', NULL, '2026-07-13 05:39:13', '2026-07-20 02:37:14', 1),
	(17, 8, 18, 'Public Safety Campaign Management System', 'SEEDER: Demo Ready ? Fire Extinguisher Practical for Volunteers', '2026-06-23 05:40:39', '2026-07-11 05:40:39', 'scheduled', 19, 13, 0, '{"submitted_at":"2026-06-23T13:40:39+08:00","training_title":"Earthquake Drill and Evacuation","_test_seeder":"simulation_event_planning_demo","training_module_id":8,"short_description":"Scenario-based training on earthquake drills, drop-cover-hold, and evacuation to safe zones.","recommended_communities":{"summary":{"total_communities":1,"high_priority":1,"medium_priority":0,"low_priority":0},"communities":[{"barangay_name":"Greater Lagro","priority":"high","hazard_score":82}]},"target_audience":["Barangay Officials","Community Volunteers","Emergency Responders"],"registration_opens":"2026-06-22T13:40:39+08:00","registration_deadline":"2026-07-10T13:40:39+08:00","training_completion_deadline":"2026-07-12T13:40:39+08:00","expected_participants":19,"maximum_participants":29,"published_status":"published","registration_enabled":true,"registration_link":"http:\\/\\/127.0.0.1:8000\\/participant\\/register?campaign_request=17","registration_form_path":"\\/participant\\/register"}', NULL, '2026-07-13 05:39:19', '2026-07-20 02:37:14', 1),
	(18, 5, 22, 'Public Safety Campaign Management System', 'SEEDER: Demo Ready ? Flood Rescue Coordination Exercise', '2026-06-23 05:40:43', '2026-07-11 05:40:43', 'scheduled', 23, 16, 0, '{"submitted_at":"2026-06-23T13:40:43+08:00","training_title":"Fire Safety and Emergency Response","_test_seeder":"simulation_event_planning_demo","training_module_id":5,"short_description":"This training module equips participants with the fundamental knowledge and practical skills needed to prevent, respond to, and safely evacuate during fire-related emergencies. Participants will learn fire prevention strategies, the proper use of fire extinguishers, emergency response procedures, and evacuation protocols applicable in homes, schools, workplaces, and government facilities.","recommended_communities":{"summary":{"total_communities":1,"high_priority":1,"medium_priority":0,"low_priority":0},"communities":[{"barangay_name":"Gulod","priority":"high","hazard_score":82}]},"target_audience":["Barangay Officials","Community Volunteers","Emergency Responders"],"registration_opens":"2026-06-22T13:40:43+08:00","registration_deadline":"2026-07-10T13:40:43+08:00","training_completion_deadline":"2026-07-12T13:40:43+08:00","expected_participants":23,"maximum_participants":33,"published_status":"published","registration_enabled":true,"registration_link":"http:\\/\\/127.0.0.1:8000\\/participant\\/register?campaign_request=18","registration_form_path":"\\/participant\\/register"}', NULL, '2026-07-13 05:39:22', '2026-07-26 09:23:45', 1),
	(19, 5, NULL, 'Public Safety Campaign Management System', 'Registration: Jun 29, 2026 – Jul 20, 2026', '2026-07-26 07:52:39', NULL, 'waiting_for_approval', 20, 13, 0, '{"submitted_at":"2026-07-26T15:52:39+08:00","training_module_id":5,"training_title":"Fire Safety and Emergency Response","short_description":"This training module equips participants with the fundamental knowledge and practical skills needed to prevent, respond to, and safely evacuate during fire-related emergencies. Participants will learn fire prevention strategies, the proper use of fire extinguishers, emergency response procedures, and evacuation protocols applicable in homes, schools, workplaces, and government facilities.","recommended_communities":{"summary":{"total_communities":1,"high_priority":0,"medium_priority":1,"low_priority":0},"communities":[{"barangay_profile_id":9,"barangay_name":"San Agustin","municipality_city":"Quezon City","province":"Metro Manila","related_hazard":"Fire","risk_level":"Medium","exposure_scope":"pattern_based","focus_area":"Dense residential clusters \\/ closely packed houses and narrow access lanes in San Agustin \\u2014 fire can ignite anywhere, but spread risk is higher where homes are adjacent and egress is constrained (pattern-based, not one fixed street).","priority_level":"Priority 2","priority_score":50,"recommendation_reason":"San Agustin matches this training because Hazard Assessment records moderate fire risk (focus: Dense residential clusters \\/ closely packed houses and narrow access lanes in San Agustin \\u2014 fire can ignite anywhere, but spread risk is higher where homes are adjacent and egress is constrained (pattern-based, not one fixed street).), supported by Urban fire risk in dense residential blocks (BFP \\/ LGU preparedness context) (2024).","recommendation":"San Agustin matches this training because Hazard Assessment records moderate fire risk (focus: Dense residential clusters \\/ closely packed houses and narrow access lanes in San Agustin \\u2014 fire can ignite anywhere, but spread risk is higher where homes are adjacent and egress is constrained (pattern-based, not one fixed street).), supported by Urban fire risk in dense residential blocks (BFP \\/ LGU preparedness context) (2024).","reference_title":"Urban fire risk in dense residential blocks (BFP \\/ LGU preparedness context)","reference_year":2024}]},"target_audience":["residents","barangay_officials","emergency_responders","community_leaders"],"registration_opens":"2026-06-29T05:40:00+08:00","registration_deadline":"2026-07-20T05:40:00+08:00","training_completion_deadline":"2026-07-30T05:40:00+08:00","expected_participants":20,"maximum_participants":30,"published_status":"published","registration_enabled":true,"registration_link":"http:\\/\\/127.0.0.1:8000\\/campaigns\\/19\\/register","registration_form_path":"\\/campaigns\\/19\\/register"}', '{"campaign_system_outbound":{"success":false,"error":"SQLSTATE[22001]: String data, right truncated: 1406 Data too long for column \'location\' at row 1","attempted_at":"2026-07-26T15:52:40+08:00"}}', '2026-07-26 07:52:39', '2026-07-26 07:52:40', 3);
