REPLACE INTO `training_modules` (`id`, `title`, `short_description`, `description`, `learning_objectives`, `estimated_duration_minutes`, `recommended_audience`, `thumbnail_path`, `difficulty`, `category`, `related_hazard`, `delivery_method`, `target_audience`, `status`, `visibility`, `owner_id`, `lead_qualified_trainer_id`, `assigned_qualified_trainer_ids`, `lead_trainer_id`, `trainer_availability`, `available_training_sessions`, `campaign_registration_opens`, `campaign_registration_deadline`, `campaign_training_completion_deadline`, `campaign_expected_participants`, `campaign_maximum_participants`, `campaign_registration_enabled`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(5, 'Fire Safety and Emergency Response', 'This training module equips participants with the fundamental knowledge and practical skills needed to prevent, respond to, and safely evacuate during fire-related emergencies. Participants will learn fire prevention strategies, the proper use of fire extinguishers, emergency response procedures, and evacuation protocols applicable in homes, schools, workplaces, and government facilities.', 'This training module equips participants with the fundamental knowledge and practical skills needed to prevent, respond to, and safely evacuate during fire-related emergencies. Participants will learn fire prevention strategies, the proper use of fire extinguishers, emergency response procedures, and evacuation protocols applicable in homes, schools, workplaces, and government facilities.', '["Understand the basic principles of fire safety.","Identify the common causes of fire incidents.","Apply effective fire prevention practices.","Recognize the different types of fire extinguishers and their appropriate uses.","Demonstrate the proper PASS technique when operating a fire extinguisher.","Follow the correct emergency response and evacuation procedures during a fire incident."]', 60, NULL, 'training-module-thumbnails/5J7rKA7ACj0w5MUNtedpX4WTnWai5jc5vEhf2dXu.png', 'Intermediate', 'Fire', 'Fire', 'in_person', '["residents","barangay_officials","emergency_responders","community_leaders"]', 'published', 'all', 3, 5, '[5,1]', NULL, NULL, '[{"title":"Fire Safety and Emergency Response - Session 1","date":"2026-07-10","start_time":"13:28","end_time":"14:28","delivery_method":"online","venue":"","online_platform":"google_meet","meeting_link":"https:\\/\\/workspace.google.com\\/products\\/meet\\/?utm_source=google&utm_medium=cpc&utm_campaign=1713702-Workspace-DR-APAC-PH-en-Google-BKWS-BRO-Hybrid-Others&utm_content=c-Hybrid+%7C+BKWS+-+BRO+%7C+Txt-Meet-N\\/A+1-297900019805&utm_term=google%20meet&gclsrc=aw.ds&gad_source=1&gad_campaignid=18195926841&gclid=CjwKCAjw6rfSBhAqEiwA_yocpowGRU-kH0T63lHwhYliKozeMpjXCnZooY_sSJqjQQH1PH9aDKP9MRoCdkUQAvD_BwE","maximum_participants":30}]', '2026-06-29 05:40:00', '2026-07-20 05:40:00', '2026-07-30 05:40:00', 20, 30, 1, '2026-06-27 07:11:29', '2026-07-26 07:52:38', NULL);
