	(6, 'Basic Fire Safety and Evacuation', NULL, 'Foundational concepts on fire behavior, evacuation routes, and community response.', '["Identify common fire hazards in barangay settings.","Execute basic evacuation procedures.","Coordinate with local fire responders."]', 60, NULL, NULL, 'Beginner', 'Fire Safety', NULL, NULL, NULL, 'published', 'all', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-07-08 20:19:46', '2026-07-08 20:20:46', '2026-07-08 20:20:46'),
	(7, 'Flood Preparedness and Early Warning', NULL, 'Training module focused on rainfall monitoring, flood mapping, and early warning communication.', '["Interpret simple weather and flood advisories.","Map flood-prone areas in the community.","Design an early warning notification flow."]', 90, NULL, NULL, 'Intermediate', 'Flood', NULL, NULL, '["Barangay Officials","Community Volunteers"]', 'published', 'all', 1, NULL, NULL, NULL, NULL, NULL, '2026-06-29 13:40:55', '2026-07-10 13:40:55', '2026-07-20 13:40:55', 24, 34, 1, '2026-07-08 20:19:46', '2026-07-13 05:40:55', NULL),
	(8, 'Earthquake Drill and Evacuation', NULL, 'Scenario-based training on earthquake drills, drop-cover-hold, and evacuation to safe zones.', '["Perform drop-cover-hold correctly.","Identify safe evacuation routes and assembly points.","Coordinate with barangay disaster volunteers."]', 45, NULL, NULL, 'Intermediate', 'Earthquake', NULL, NULL, '["Barangay Officials","Community Volunteers"]', 'published', 'all', 1, NULL, NULL, NULL, NULL, NULL, '2026-06-29 13:40:58', '2026-07-12 13:40:58', '2026-07-22 13:40:58', 22, 32, 1, '2026-07-08 20:19:46', '2026-07-13 05:40:58', NULL),
	(9, 'Earthquake Drill and Evacuation', NULL, 'Scenario-based training on earthquake drills, drop-cover-hold, and evacuation to safe zones.', '["Perform drop-cover-hold correctly.","Identify safe evacuation routes and assembly points.","Coordinate with barangay disaster volunteers."]', 45, NULL, NULL, 'Intermediate', 'Earthquake', NULL, NULL, NULL, 'published', 'all', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-07-13 06:13:27', '2026-07-13 09:19:36', '2026-07-13 09:19:36');
